BEGIN;
SET LOCAL lock_timeout = '5000ms';
SET LOCAL statement_timeout = '30000ms';
CREATE TABLE identity.registration_intents (id UUID NOT NULL, email_normalized TEXT NOT NULL, generation BIGINT NOT NULL DEFAULT 1, intent_state TEXT NOT NULL DEFAULT 'pending', created_at TIMESTAMP WITH TIME ZONE NOT NULL, expires_at TIMESTAMP WITH TIME ZONE NOT NULL, next_delivery_at TIMESTAMP WITH TIME ZONE NOT NULL, consumed_at TIMESTAMP WITH TIME ZONE);
CREATE UNIQUE INDEX registration_intents_id_uidx ON identity.registration_intents (id);
CREATE UNIQUE INDEX registration_intents_email_uidx ON identity.registration_intents (email_normalized);
ALTER TABLE identity.registration_intents ADD CONSTRAINT registration_intents_state_check CHECK (intent_state IN ('pending','consumed','expired','cancelled'));
ALTER TABLE identity.registration_intents ADD CONSTRAINT registration_intents_generation_check CHECK (generation > 0);
CREATE TABLE identity.email_verification_tokens (id UUID NOT NULL, intent_id UUID NOT NULL, generation BIGINT NOT NULL, purpose TEXT NOT NULL, token_hash TEXT NOT NULL, created_at TIMESTAMP WITH TIME ZONE NOT NULL, expires_at TIMESTAMP WITH TIME ZONE NOT NULL, consumed_at TIMESTAMP WITH TIME ZONE);
CREATE UNIQUE INDEX email_verification_tokens_id_uidx ON identity.email_verification_tokens (id);
CREATE UNIQUE INDEX email_verification_tokens_hash_uidx ON identity.email_verification_tokens (token_hash);
ALTER TABLE identity.email_verification_tokens ADD CONSTRAINT email_verification_tokens_intent_fk FOREIGN KEY (intent_id) REFERENCES identity.registration_intents (id) ON DELETE CASCADE;
ALTER TABLE identity.email_verification_tokens ADD CONSTRAINT email_verification_tokens_purpose_check CHECK (purpose IN ('new_registration'));
ALTER TABLE identity.email_verification_tokens ADD CONSTRAINT email_verification_tokens_generation_check CHECK (generation > 0);
CREATE TABLE identity.user_email_verifications (user_id UUID NOT NULL, evidence_state TEXT NOT NULL, verified_at TIMESTAMP WITH TIME ZONE);
CREATE UNIQUE INDEX user_email_verifications_user_uidx ON identity.user_email_verifications (user_id);
ALTER TABLE identity.user_email_verifications ADD CONSTRAINT user_email_verifications_user_fk FOREIGN KEY (user_id) REFERENCES identity.users (id) ON DELETE CASCADE;
ALTER TABLE identity.user_email_verifications ADD CONSTRAINT user_email_verifications_state_check CHECK (evidence_state IN ('legacy_unverified','verified'));
CREATE TABLE identity.email_delivery_jobs (id UUID NOT NULL, intent_id UUID NOT NULL, generation BIGINT NOT NULL, job_state TEXT NOT NULL, attempts INTEGER NOT NULL DEFAULT 0, available_at TIMESTAMP WITH TIME ZONE NOT NULL, lease_id UUID, lease_until TIMESTAMP WITH TIME ZONE, expires_at TIMESTAMP WITH TIME ZONE NOT NULL);
CREATE UNIQUE INDEX email_delivery_jobs_id_uidx ON identity.email_delivery_jobs (id);
CREATE UNIQUE INDEX email_delivery_jobs_intent_uidx ON identity.email_delivery_jobs (intent_id);
ALTER TABLE identity.email_delivery_jobs ADD CONSTRAINT email_delivery_jobs_intent_fk FOREIGN KEY (intent_id) REFERENCES identity.registration_intents (id) ON DELETE CASCADE;
ALTER TABLE identity.email_delivery_jobs ADD CONSTRAINT email_delivery_jobs_state_check CHECK (job_state IN ('queued','leased','delivered','failed','cancelled'));
ALTER TABLE identity.email_delivery_jobs ADD CONSTRAINT email_delivery_jobs_attempt_min_check CHECK (attempts >= 0);
ALTER TABLE identity.email_delivery_jobs ADD CONSTRAINT email_delivery_jobs_attempt_max_check CHECK (attempts <= 4);
COMMIT;
